<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { eliminarCuadrilla, guardarCuadrilla, listarCuadrillas } from '../services/cuadrillas'
import type { Cuadrilla, CuadrillaPayload, PersonalOperativo } from '../interfaces/cuadrillas.interface'
const records=ref<Cuadrilla[]>([]),staff=ref<PersonalOperativo[]>([]),serviceTypes=ref<Record<number,string>>({}),query=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),memberId=ref<number|null>(null),total=ref(0),summary=reactive({activas:0,personal_asignado:0,trabajos_pendientes:0}),form=reactive<CuadrillaPayload>({nombre:'',tipo_servicio_id:null,lider_id:null,miembros_ids:[],activa:true})
const selectedMembers=computed(()=>form.miembros_ids.map(id=>staff.value.find(x=>x.id===id)).filter((x):x is PersonalOperativo=>Boolean(x))),availableStaff=computed(()=>staff.value.filter(x=>!form.miembros_ids.includes(x.id)))
async function load(){loading.value=true;error.value='';try{const r=await listarCuadrillas(query.value);records.value=r.data;staff.value=r.personal;serviceTypes.value=r.tipos_servicio;total.value=r.total;Object.assign(summary,r.resumen)}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:Cuadrilla){editing.value=item?.id??null;Object.assign(form,item?{nombre:item.nombre,tipo_servicio_id:item.tipo_servicio_id,lider_id:item.lider_id,miembros_ids:item.miembros.map(x=>x.id),activa:item.activa}:{nombre:'',tipo_servicio_id:null,lider_id:null,miembros_ids:[],activa:true});memberId.value=null;modal.value=true;error.value=''}
function add(){if(!memberId.value)return;if(!form.miembros_ids.includes(memberId.value))form.miembros_ids.push(memberId.value);memberId.value=null}function removeMember(id:number){form.miembros_ids=form.miembros_ids.filter(x=>x!==id);if(form.lider_id===id)form.lider_id=null}
async function save(){if(!form.nombre.trim()||!form.tipo_servicio_id||!form.lider_id){error.value='Complete la denominación, tipo de servicio y líder.';return}if(!form.miembros_ids.includes(form.lider_id)){error.value='El líder debe formar parte del personal de la cuadrilla.';return}if(form.miembros_ids.length<2){error.value='Agregue al menos dos integrantes a la cuadrilla.';return}saving.value=true;try{await guardarCuadrilla(form,editing.value??undefined);modal.value=false;success.value=`Cuadrilla ${editing.value?'actualizada':'registrada'} correctamente.`;await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:Cuadrilla){if(item.trabajos_pendientes>0){error.value='No se puede eliminar una cuadrilla con trabajos pendientes.';return}if(!confirm(`¿Eliminar la cuadrilla ${item.nombre}?`))return;try{await eliminarCuadrilla(item.id);success.value='Cuadrilla eliminada.';await load()}catch(e){error.value=message(e)}}const clear=()=>{query.value='';load()};const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Cuadrillas operativas</nav><header class="hero"><div class="mark">CU</div><div><small>DANA · OPERACIÓN EN CAMPO</small><h1>Cuadrillas operativas</h1><p>Organiza líderes y personal para la atención de servicios de campo.</p></div><button @click="open()">+ Registrar cuadrilla</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="summary"><article><small>CUADRILLAS REGISTRADAS</small><b>{{total}}</b></article><article><small>CUADRILLAS ACTIVAS</small><b>{{summary.activas}}</b></article><article><small>PERSONAL ASIGNADO</small><b>{{summary.personal_asignado}}</b></article><article><small>TRABAJOS PENDIENTES</small><b>{{summary.trabajos_pendientes}}</b></article></section><form class="filters" @submit.prevent="load"><label>Buscar cuadrilla o trabajador<input v-model.trim="query" placeholder="Denominación, líder o integrante"></label><button>Buscar</button><button v-if="query" type="button" class="soft" @click="clear">Limpiar</button></form><div v-if="loading" class="empty">Cargando cuadrillas…</div><div v-else-if="!records.length" class="empty">No se encontraron cuadrillas registradas.</div><section v-else class="cards"><article v-for="item in records" :key="item.id" :class="{inactive:!item.activa}"><header><div class="team">{{item.miembros.length}}</div><div><small>CUADRILLA #{{item.id}}</small><h2>{{item.nombre}}</h2></div><span>{{item.activa?'ACTIVA':'INACTIVA'}}</span></header><p class="service">{{item.tipo_servicio}}</p><div class="leader"><small>LÍDER DE CUADRILLA</small><b>★ {{item.lider}}</b></div><ul><li v-for="member in item.miembros" :key="member.id"><span>{{member.nombre}}</span><small>{{member.cargo}}</small><b v-if="member.lider">Líder</b></li></ul><div class="work"><span><b>{{item.trabajos_pendientes}}</b> pendientes</span><span><b>{{item.trabajos_atendidos}}</b> atendidos</span></div><footer><button @click="open(item)">Modificar</button><button class="delete" :disabled="item.trabajos_pendientes>0" @click="remove(item)">Eliminar</button></footer></article></section>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>ORGANIZACIÓN DEL PERSONAL</small><h2>{{editing?'Modificar':'Registrar'}} cuadrilla</h2></div><button type="button" @click="modal=false">×</button></header><div class="fields"><label>Denominación *<input v-model.trim="form.nombre" maxlength="100" placeholder="Ej. Cuadrilla Agua Norte"></label><label>Tipo de servicio *<select v-model="form.tipo_servicio_id"><option :value="null">Seleccione</option><option v-for="(name,key) in serviceTypes" :key="key" :value="Number(key)">{{name}}</option></select></label><label class="check"><input v-model="form.activa" type="checkbox"> Cuadrilla activa</label></div><section class="members"><header><div><small>PERSONAL OPERATIVO</small><h3>Integrantes de la cuadrilla</h3></div></header><div class="add"><select v-model="memberId"><option :value="null">Seleccione personal</option><option v-for="person in availableStaff" :key="person.id" :value="person.id" :disabled="!person.disponible">{{person.nombre}} · {{person.cargo}}{{person.disponible?'':' (asignado)'}}</option></select><button type="button" @click="add">Agregar</button></div><div v-if="!selectedMembers.length" class="member-empty">Agregue el líder y demás integrantes.</div><article v-for="person in selectedMembers" :key="person.id"><div><b>{{person.nombre}}</b><span>{{person.cargo}}</span></div><label><input v-model="form.lider_id" type="radio" name="leader" :value="person.id"> Líder</label><button type="button" @click="removeMember(person.id)">Quitar</button></article></section><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar cuadrilla'}}</button></footer></form></div></div></template>
